fig = plt.gcf(); fig.set_size_inches(6.8, 3.4)
ax = fig.add_axes([0, 0, 1, 1]); ax.axis('off')
def d(x, y, s, size=20, color='black', **k):
    ax.text(x, y, s, ha='center', va='center', fontsize=size, color=color, **k)
def bar(x1, x2, y):
    ax.plot([x1, x2], [y, y], color='black', lw=1.5)
def strike(x, y, w=0.2):
    ax.plot([x - w, x + w], [y - 0.28, y + 0.28], color='red', lw=1.8)
from matplotlib.patches import Rectangle
S = 0.28
def rod(x, y, fc='white', hatch=None, crossed=False):
    for k in range(10):
        ax.add_patch(Rectangle((x, y + k * S), S, S, fc=fc, ec='black', lw=0.8, hatch=hatch))
    if crossed:
        ax.plot([x - 0.1, x + S + 0.1], [y - 0.05, y + 10 * S + 0.05], color='red', lw=2)
def one(x, y, fc='white', hatch=None, crossed=False):
    ax.add_patch(Rectangle((x, y), S, S, fc=fc, ec='black', lw=0.8, hatch=hatch))
    if crossed:
        ax.plot([x + 0.04, x + S - 0.04], [y + 0.04, y + S - 0.04], color='red', lw=1.6)
        ax.plot([x + 0.04, x + S - 0.04], [y + S - 0.04, y + 0.04], color='red', lw=1.6)
blue = (0.75, 0.85, 1.0)

# 7 rods: 4 plain, 3 striped
for i in range(7):
    if i < 4: rod(0.2 + i * 0.4, 0.5)
    else: rod(0.2 + i * 0.4, 0.5, blue, '////')
# 15 ones in 3 columns of 5: first 7 plain, next 8 striped
for j in range(15):
    c, r = divmod(j, 5)
    if j < 7: one(3.2 + c * 0.4, 0.5 + r * 0.4)
    else: one(3.2 + c * 0.4, 0.5 + r * 0.4, blue, '////')
ax.add_patch(Rectangle((3.12, 0.42), 0.84, 2.04, fill=False, ec='red', lw=1.8, ls='--'))
